properties.query:
let windowSize = 2h;
let AoiBounds = _GetWatchlist('AOI_Boundary_List')
    | project MinLat=toreal(MinLat), MaxLat=toreal(MaxLat),
              MinLon=toreal(MinLon), MaxLon=toreal(MaxLon);
let minSpeed = toscalar(
    _GetWatchlist('UAV_Threshold_List')
    | where ThresholdKey == 'MinGroundspeed_ms'
    | project toreal(Value));
// S12: 임무 자기승인 (PlanId 사용)
let S12 =
    UAVMissionPlan_CL
    | where TimeGenerated > ago(windowSize)
    | where Planner == Approver
    | project T1=TimeGenerated, UAVId=tostring(UAVId), PlanId, Planner;
// S16: AOI 이탈 (Groundspeed_ms, UAVId 기반)
let S16 =
    UAVTelemetry_CL
    | where TimeGenerated > ago(windowSize)
    | where MsgType == 'GLOBAL_POSITION_INT'
    | where Groundspeed_ms > minSpeed
    | where isnotnull(Lat) and isnotnull(Lon)
    | join kind=leftanti (AoiBounds) on
        $left.Lat >= $right.MinLat and $left.Lat <= $right.MaxLat
        and $left.Lon >= $right.MinLon and $left.Lon <= $right.MaxLon
    | summarize ExcursionCount=count(), T2=min(TimeGenerated) by UAVId=tostring(UAVId)
    | where ExcursionCount >= 3;
// S3: SATCOM 무결성 이상
let S3 =
    UAVSatcomLink_CL
    | where TimeGenerated > ago(windowSize)
    | where IntegrityStatus != 'ok' or toreal(JamIndicator) > 0.15
    | summarize T3=min(TimeGenerated) by UAVId=tostring(UAVId);
S12
| join kind=inner (S16) on UAVId
| where T2 >= T1 and T2 <= T1 + 60m
| join kind=inner (S3) on UAVId
| where T3 >= T2 and T3 <= T2 + 60m
| extend CampaignType = "C3_자기승인임무_AOI이탈_SATCOM유출"
| extend StepSummary = strcat("S12@", tostring(T1), "(PlanId:", PlanId, ")→S16@", tostring(T2), "→S3@", tostring(T3))
| extend Severity = "High"
| project T1, T2, T3, UAVId, PlanId, Planner, CampaignType, StepSummary, Severity
